/**
 * Host for the embedded Concert Grand DSP module.
 *
 * The wasm payload is checked-in source (`./wasm/concert-grand-wasm.ts`,
 * generated by `scripts/build-dsp.ts` from `dsp/concert-grand`). This module
 * decodes and instantiates it once, owns its linear memory layout, and turns
 * `(midiPitch, velocity, sampleRate)` into freshly copied stereo PCM. Renders
 * are bit-deterministic: the module imports nothing from the host — no clock,
 * no random device, no I/O — so the PCM goldens can pin exact hashes.
 *
 * The shipping `@1` note remains a HYBRID: its first third of a second comes
 * from a recorded Yamaha C5 (`./wasm/piano-attack-samples.ts`). A separate,
 * optional `@2` evidence surface cooperatively renders a finite-mass felt
 * hammer, stiff unison strings, bridge, and orthotropic soundboard entirely
 * inside WASM. It stays dark until its independent reference and owner
 * listening gates pass; merely compiling that ABI is not a route decision.
 *
 * Layer position: audio-internal. The engine caches the PCM in Web Audio
 * buffers; no other layer sees this module or the wasm instance.
 */
import {
  CONCERT_GRAND_WASM_BASE64,
  CONCERT_GRAND_WASM_BYTE_LENGTH,
  CONCERT_GRAND_WASM_SHA256,
} from "./wasm/concert-grand-wasm";
import {
  PIANO_ATTACK_SAMPLE_RATE_HZ,
  PIANO_ATTACK_SAMPLES_ATTRIBUTION,
  PIANO_ATTACK_SAMPLES_BASE64,
  PIANO_ATTACK_SAMPLES_BYTE_LENGTH,
  PIANO_ATTACK_SAMPLES_LICENSE,
  PIANO_ATTACK_SAMPLES_SHA256,
  PIANO_ATTACK_SLICE_INDEX,
  type PianoAttackSlice,
} from "./wasm/piano-attack-samples";
import type {
  PhysicalRenderAbiRequestV2,
  PhysicalRenderRefusalCode,
} from "./physical-renderer-contract";

