export type WaveguideRenderer = Readonly<{
  algorithmId: string;
  wasmSha256: string;
  /**
   * Render one note; same contract shape as the Concert Grand's
   * `renderNote`. Null only for an out-of-contract request.
   */
  renderNote: (
    midiPitch: number,
    velocity: number,
    sampleRateHz: number,
    maxSeconds?: number,
    variationSlot?: number,
    windArticulation?: WindAttackArticulation,
  ) => RenderedNotePcm | null;
  /**
   * One simultaneous plucked-instrument chord through one shared body and
   * amplifier. Present only when the embedded WASM carries the chord ABI.
   */
  renderChord?: (
    midiPitches: readonly number[],
    velocities: readonly number[],
    sampleRateHz: number,
    maxSeconds?: number,
  ) => RenderedNotePcm | null;
  /**
   * Bit-identical chord preparation through bounded WASM chunks. Each
   * incomplete chunk yields one browser macrotask. The production ABI retains
   * one opaque session in the single-threaded WASM instance and the host
   * serializes access; the checksummed caller-owned ABI remains available for
   * independent continuity and hostile-state tests.
   */
  renderChordCooperatively?: (
    midiPitches: readonly number[],
    velocities: readonly number[],
    sampleRateHz: number,
    maxSeconds?: number,
  ) => Promise<RenderedNotePcm | null>;
  /** Stateful physical phrase path, present only on clarinet v2. */
  renderPhraseSegment?: (
    midiPitch: number,
    velocity: number,
    sampleRateHz: number,
    frameCount: number,
    stateInput: Uint8Array | null,
    variationSlot: number,
    windArticulation: WindAttackArticulation,
  ) => PhysicalClarinetPhraseRenderResult | null;
  /**
   * Explicit retained plucked-instrument stem. Unlike `renderNote`, this path
   * carries all strings, body modes, contact, amp, and radiation history
   * between bounded segments; `reset` is the deterministic Stop operation.
   */
  renderPluckedStemSegment?: (
    midiPitch: number | null,
    velocity: number,
    sampleRateHz: number,
    frameCount: number,
    stateInput: Uint8Array | null,
    reset: boolean,
  ) => PhysicalPluckedStemRenderResult | null;
}>;

/**
 * The reviewed crossfade design. The sampled attack owns the note outright
 * until `sampleOnlySeconds`; a cosine/sine crossfade then hands the note to
 * the synthesized sustain by `crossfadeEndSeconds`.
 *
 * Equal power alone would be the wrong law. It assumes the two layers are
 * uncorrelated, and these two are not: they are the same note, they both
 * begin at the onset, and the build-time stretch correction deliberately
 * puts their fundamentals on one frequency, so their relative phase is fixed
 * for the whole handover. Measured across the keyboard that correlation runs
 * from -0.97 to +0.99, and where it is negative the two layers cancel — a
 * hole up to 14.4 dB deep in the middle of the crossfade. The weights are
 * therefore corrected for the coherence the note actually has; see
 * `applyAttackLayer`.
 */
export const PIANO_ATTACK_LAYER_POLICY = Object.freeze({
  id: "changes.dsp.piano-attack-layer.v1",
  attribution: PIANO_ATTACK_SAMPLES_ATTRIBUTION,
  license: PIANO_ATTACK_SAMPLES_LICENSE,
  payloadSha256: PIANO_ATTACK_SAMPLES_SHA256,
  sampleOnlySeconds: 0.18,
  crossfadeEndSeconds: 0.32,
  /**
   * Level is matched twice: once over the attack the sampled layer owns, and
   * once over the crossfade window it hands off in. A recorded string and a
   * modelled one do not decay at quite the same rate, so a single match would
   * either misstate the attack's loudness or step at the seam. The correction
   * interpolates log-linearly in time between the two — the exact shape that
   * turns one exponential decay into another — and is clamped so a badly
   * mismatched pair degrades instead of exploding.
   */
  attackWindowStartSeconds: 0.02,
  attackWindowEndSeconds: 0.18,
  matchWindowStartSeconds: 0.18,
  matchWindowEndSeconds: 0.32,
  maximumDecayCorrectionRatio: 4,
  /** A recorded key is never stretched further than this. */
  maximumTranspositionSemitones: 3,
  /** The sampled layer is ducked before the hybrid can exceed this. */
  peakCeiling: 0.945,
  /** How fast that duck may move, so it can never be heard as a step. */
  peakGuardSlewDecibelsPerSecond: 60,
  interpolation: "catmull-rom",
} as const);

/**
 * Sample-free handoff from the finite-hammer PNO2 attack to the existing
 * deterministic long-decay string bank. The timing mirrors the reviewed @1
 * handoff so an eventual @2 comparison changes the source, not the gesture.
 */
export const PHYSICAL_PIANO_ATTACK_LAYER_POLICY = Object.freeze({
  id: "changes.dsp.piano-physical-attack-layer.v1",
  physicalOnlySeconds: 0.18,
  crossfadeEndSeconds: 0.32,
  attackWindowStartSeconds: 0.02,
  attackWindowEndSeconds: 0.18,
  matchWindowStartSeconds: 0.24,
  matchWindowEndSeconds: 0.32,
  maximumDecayCorrectionRatio: 4,
  peakCeiling: 0.945,
  maximumPhysicalSampleMagnitude: 0.98,
  peakGuardSlewDecibelsPerSecond: 60,
} as const);

export type RenderedNotePcm = Readonly<{
  sampleRateHz: number;
  frameCount: number;
  left: Float32Array<ArrayBuffer>;
  right: Float32Array<ArrayBuffer>;
}>;

export type DetectedNote = Readonly<{
  midiPitch: number;
  centsDeviation: number;
  strength: number;
}>;

export type AnalysisFrame = Readonly<{
  sampleRateHz: number;
  fftSize: number;
  /** Hann-windowed magnitude spectrum, fftSize/2 bins. */
  magnitudes: Float32Array<ArrayBuffer>;
  /** Harmonically grouped fundamentals, strongest first. */
  notes: readonly DetectedNote[];
  /** Pitch-class energy fold (C first), unit-maximum normalized. */
  chroma: Float32Array<ArrayBuffer>;
}>;

export type PhysicalModalState = Readonly<{ x: number; y: number }>;
export type PhysicalEnergyLedger = Readonly<{
  initialEnergy: number;
  excitationWork: number;
  finalEnergy: number;
  /** Independently accumulated per-sample loss-coefficient absorption. */
  dampingLoss: number;
  /** initial + work - final - dampingLoss; a genuine closure check. */
  residual: number;
}>;
export type PhysicalModalRenderResult = RenderedNotePcm & Readonly<{
  state: PhysicalModalState;
  energy: PhysicalEnergyLedger;
  limiterEngagements: number;
}>;
export type PhysicalReedSolveResult = Readonly<{
  junctionPressure: number;
  volumeFlow: number;
  nonlinearIterations: number;
  fallbackBisections: number;
}>;
export type PhysicalClarinetReedState = Readonly<{
  displacementM: number;
  velocityMPerS: number;
}>;
export type PhysicalClarinetReedStepResult = Readonly<{
  state: PhysicalClarinetReedState;
  signedVolumeFlowM3PerS: number;
  collisionLossJ: number;
  mechanicalEnergyBeforeJ: number;
  mechanicalEnergyAfterJ: number;
  tongueForceN: number;
  contact: boolean;
}>;
export type PhysicalClarinetPhraseRenderResult = RenderedNotePcm & Readonly<{
  stateOutput: Uint8Array<ArrayBuffer>;
}>;

export type ConcertGrandRenderer = Readonly<{
  algorithmId: typeof CONCERT_GRAND_RENDERER_ALGORITHM_ID;
  wasmSha256: string;
  attackSamplesSha256: string;
  physicalAttackAlgorithmId?: typeof CONCERT_GRAND_PHYSICAL_V2_ALGORITHM_ID;
  /**
   * Render one note: the recorded attack crossfaded into the synthesized
   * sustain. Synchronous and pure after instantiation; returns null only for
   * an out-of-contract request (pitch outside 21..108, velocity outside
   * 1..127, unsupported sample rate). A note the sample corpus cannot serve
   * still renders — as pure synthesis.
   */
  renderNote: (
    midiPitch: number,
    velocity: number,
    sampleRateHz: number,
    /**
     * Optional ceiling on the rendered length, seconds. A performance holds
     * most notes for a fraction of their natural decay, and rendering the
     * full eight-second bass tail only to gate it off after half a second
     * costs more than an order of magnitude of the work. The tail is trimmed
     * with a short fade so a truncated render cannot click.
     */
    maxSeconds?: number,
  ) => RenderedNotePcm | null;
  /**
   * The same note with the sampled attack layer withheld. Evidence surface
   * only: it exists so a test can prove the layer changes the tone, and the
   * engine never calls it.
   */
  renderSynthesizedNote: (
    midiPitch: number,
    velocity: number,
    sampleRateHz: number,
  ) => RenderedNotePcm | null;
  /** Sample-free legacy sustain rendered in bounded yielded WASM steps. */
  renderSynthesizedNoteCooperatively?: (
    midiPitch: number,
    velocity: number,
    sampleRateHz: number,
    maxSeconds?: number,
  ) => Promise<RenderedNotePcm | null>;
  /**
   * Dark sample-free attack candidate. Each incomplete 256-frame WASM step
   * yields a browser macrotask, and all retained-runtime access is serialized.
   * This method is absent when the embedded module lacks the complete PNO2
   * runtime ABI; callers must never fall back to a recorded attack silently.
   */
  renderPhysicalAttackCooperatively?: (
    midiPitch: number,
    velocity: number,
    sampleRateHz: number,
    maxSeconds?: number,
  ) => Promise<RenderedNotePcm | null>;
  /**
   * Dark simultaneous-key onset. All keys share one retained physical
   * soundboard; this is not a mixer of independently rendered note buffers.
   */
  renderPhysicalChordAttackCooperatively?: (
    midiPitches: readonly number[],
    velocities: readonly number[],
    sampleRateHz: number,
    maxSeconds?: number,
  ) => Promise<RenderedNotePcm | null>;
  /** Dark complete note using PNO2 for the onset and no recorded PCM. */
  renderPhysicalNoteCooperatively?: (
    midiPitch: number,
    velocity: number,
    sampleRateHz: number,
    maxSeconds?: number,
  ) => Promise<RenderedNotePcm | null>;
  /**
   * The recorded slice `renderNote` would use, or null when the request
   * falls outside the sampled set. Evidence surface only.
   */
  attackSliceFor: (
    midiPitch: number,
    velocity: number,
  ) => PianoAttackSlice | null;
  /**
   * Analyze one time-domain window: windowed FFT, spectral-peak note
   * detection with harmonic grouping, and a chroma fold. `samples.length`
   * must be a power of two in 64..8192. Null on an out-of-contract request.
   */
  analyzeWindow: (
    samples: Float32Array,
    sampleRateHz: number,
  ) => AnalysisFrame | null;
  /** Validate an ABI-v2 layout inside the Rust/WASM safety boundary. */
  validatePhysicalAbiV2: (
    request: PhysicalRenderAbiRequestV2,
    linearMemoryBytes: number,
  ) => PhysicalRenderRefusalCode | null;
  /** Render a passive shared mode with explicit state handoff and energy. */
  renderPhysicalModalV2: (request: Readonly<{
    sampleRateHz: 44_100 | 48_000 | 96_000;
    frequencyHz: number;
    dampingPerSecond: number;
    excitation: number;
    initialState: PhysicalModalState;
    frameCount: number;
  }>) => PhysicalModalRenderResult | null;
  solvePhysicalReedV2: (request: Readonly<{
    mouthPressure: number;
    borePressure: number;
    opening: number;
    stiffness: number;
    boreImpedance: number;
  }>) => PhysicalReedSolveResult | null;
  stepPhysicalClarinetReedV2: (request: Readonly<{
    dtSeconds: number;
    state: PhysicalClarinetReedState;
    mouthPressurePa: number;
    mouthpiecePressurePa: number;
    massKg: number;
    dampingNsPerM: number;
    stiffnessNPerM: number;
    equilibriumOpeningM: number;
    effectiveAreaM2: number;
    channelWidthM: number;
    airDensityKgPerM3: number;
    tongueContact: number;
  }>) => PhysicalClarinetReedStepResult | null;
}>;

