function optionalPluckedChordExports(
  rawExports: Readonly<Record<string, unknown>>,
): Pick<
  ConcertGrandExports,
  | "plk2_render_chord"
  | "plk2_chord_physical_sample_rate"
  | "plk2_chord_session_state_max_bytes"
  | "plk2_chord_session_max_steps"
  | "plk2_chord_session_init"
  | "plk2_chord_session_step"
  | "plk2_chord_runtime_init"
  | "plk2_chord_runtime_max_steps"
  | "plk2_chord_runtime_step"
  | "plk2_chord_runtime_reset"
> {
  const physicalSampleRate =
    rawExports["plk2_chord_physical_sample_rate"] === undefined
      ? undefined
      : requireExportedFunction(
        rawExports,
        "plk2_chord_physical_sample_rate",
      ) as NonNullable<ConcertGrandExports["plk2_chord_physical_sample_rate"]>;
  const renderChord = rawExports["plk2_render_chord"] === undefined
    ? undefined
    : requireExportedFunction(
      rawExports,
      "plk2_render_chord",
    ) as NonNullable<ConcertGrandExports["plk2_render_chord"]>;
  const cooperativeNames = [
    "plk2_chord_session_state_max_bytes",
    "plk2_chord_session_max_steps",
    "plk2_chord_session_init",
    "plk2_chord_session_step",
  ] as const;
  const present = cooperativeNames.filter((name) => rawExports[name] !== undefined);
  if (present.length !== 0 && present.length !== cooperativeNames.length) {
    const missing = cooperativeNames.find((name) => rawExports[name] === undefined);
    throw new Error(`DSP_WASM_EXPORT_MISSING:${missing ?? "plk2_chord_session"}`);
  }
  const cooperative = present.length === cooperativeNames.length
    ? {
      plk2_chord_session_state_max_bytes: requireExportedFunction(
        rawExports,
        "plk2_chord_session_state_max_bytes",
      ) as NonNullable<ConcertGrandExports["plk2_chord_session_state_max_bytes"]>,
      plk2_chord_session_max_steps: requireExportedFunction(
        rawExports,
        "plk2_chord_session_max_steps",
      ) as NonNullable<ConcertGrandExports["plk2_chord_session_max_steps"]>,
      plk2_chord_session_init: requireExportedFunction(
        rawExports,
        "plk2_chord_session_init",
      ) as NonNullable<ConcertGrandExports["plk2_chord_session_init"]>,
      plk2_chord_session_step: requireExportedFunction(
        rawExports,
        "plk2_chord_session_step",
      ) as NonNullable<ConcertGrandExports["plk2_chord_session_step"]>,
    }
    : {};
  const runtimeNames = [
    "plk2_chord_runtime_init",
    "plk2_chord_runtime_max_steps",
    "plk2_chord_runtime_step",
    "plk2_chord_runtime_reset",
  ] as const;
  const runtimePresent = runtimeNames.filter((name) => rawExports[name] !== undefined);
  if (runtimePresent.length !== 0 && runtimePresent.length !== runtimeNames.length) {
    const missing = runtimeNames.find((name) => rawExports[name] === undefined);
    throw new Error(`DSP_WASM_EXPORT_MISSING:${missing ?? "plk2_chord_runtime"}`);
  }
  const runtime = runtimePresent.length === runtimeNames.length
    ? {
      plk2_chord_runtime_init: requireExportedFunction(
        rawExports,
        "plk2_chord_runtime_init",
      ) as NonNullable<ConcertGrandExports["plk2_chord_runtime_init"]>,
      plk2_chord_runtime_max_steps: requireExportedFunction(
        rawExports,
        "plk2_chord_runtime_max_steps",
      ) as NonNullable<ConcertGrandExports["plk2_chord_runtime_max_steps"]>,
      plk2_chord_runtime_step: requireExportedFunction(
        rawExports,
        "plk2_chord_runtime_step",
      ) as NonNullable<ConcertGrandExports["plk2_chord_runtime_step"]>,
      plk2_chord_runtime_reset: requireExportedFunction(
        rawExports,
        "plk2_chord_runtime_reset",
      ) as NonNullable<ConcertGrandExports["plk2_chord_runtime_reset"]>,
    }
    : {};
  const hasChordSurface =
    renderChord !== undefined || present.length !== 0 || runtimePresent.length !== 0;
  if (hasChordSurface && physicalSampleRate === undefined) {
    throw new Error("DSP_WASM_EXPORT_MISSING:plk2_chord_physical_sample_rate");
  }
  return Object.freeze({
    ...(renderChord === undefined ? {} : { plk2_render_chord: renderChord }),
    ...(physicalSampleRate === undefined
      ? {}
      : { plk2_chord_physical_sample_rate: physicalSampleRate }),
    ...cooperative,
    ...runtime,
  });
}

async function instantiate(): Promise<DspCore> {
  const bytes = decodeWasmBytes();
  const { instance } = await WebAssembly.instantiate(bytes, {});
  const rawExports: Readonly<Record<string, unknown>> = instance.exports;
  const memoryCandidate = rawExports["memory"];
  if (!(memoryCandidate instanceof WebAssembly.Memory)) {
    throw new Error("DSP_WASM_EXPORT_MISSING:memory");
  }
  const heapBaseCandidate = rawExports["__heap_base"];
  const exports: ConcertGrandExports = {
    memory: memoryCandidate,
    ...(heapBaseCandidate instanceof WebAssembly.Global
      ? { __heap_base: heapBaseCandidate }
      : {}),
    /*
     * Wasm export signatures are not statically typed; each callable is
     * runtime-verified above and asserted to its concrete numeric signature.
     */
    cg_note_frames: requireExportedFunction(
      rawExports,
      "cg_note_frames",
    ) as ConcertGrandExports["cg_note_frames"],
    cg_render: requireExportedFunction(
      rawExports,
      "cg_render",
    ) as ConcertGrandExports["cg_render"],
    ...optionalConcertGrandRuntimeExports(rawExports),
    ...optionalPhysicalPianoExports(rawExports),
    ...optionalPhysicalPianoChordExports(rawExports),
    an_spectrum: requireExportedFunction(
      rawExports,
      "an_spectrum",
    ) as ConcertGrandExports["an_spectrum"],
    an_notes: requireExportedFunction(
      rawExports,
      "an_notes",
    ) as ConcertGrandExports["an_notes"],
    an_chroma: requireExportedFunction(
      rawExports,
      "an_chroma",
    ) as ConcertGrandExports["an_chroma"],
    gtr_note_frames: requireExportedFunction(
      rawExports,
      "gtr_note_frames",
    ) as ConcertGrandExports["gtr_note_frames"],
    gtr_render: requireExportedFunction(
      rawExports,
      "gtr_render",
    ) as ConcertGrandExports["gtr_render"],
    plk2_note_frames: requireExportedFunction(
      rawExports,
      "plk2_note_frames",
    ) as ConcertGrandExports["plk2_note_frames"],
    plk2_render: requireExportedFunction(
      rawExports,
      "plk2_render",
    ) as ConcertGrandExports["plk2_render"],
    ...optionalPluckedChordExports(rawExports),
    ...optionalPluckedStemExports(rawExports),
    flt_note_frames: requireExportedFunction(
      rawExports,
      "flt_note_frames",
    ) as ConcertGrandExports["flt_note_frames"],
    flt_render: requireExportedFunction(
      rawExports,
      "flt_render",
    ) as ConcertGrandExports["flt_render"],
    flt_render_seeded: requireExportedFunction(
      rawExports,
      "flt_render_seeded",
    ) as ConcertGrandExports["flt_render_seeded"],
    flt_render_expressive: requireExportedFunction(
      rawExports,
      "flt_render_expressive",
    ) as ConcertGrandExports["flt_render_expressive"],
    flt2_note_frames: requireExportedFunction(
      rawExports,
      "flt2_note_frames",
    ) as ConcertGrandExports["flt2_note_frames"],
    vbs2_note_frames: requireExportedFunction(
      rawExports,
      "vbs2_note_frames",
    ) as ConcertGrandExports["vbs2_note_frames"],
    vbs2_render: requireExportedFunction(
      rawExports,
      "vbs2_render",
    ) as ConcertGrandExports["vbs2_render"],
    flt2_state_max_bytes: requireExportedFunction(
      rawExports,
      "flt2_state_max_bytes",
    ) as ConcertGrandExports["flt2_state_max_bytes"],
    flt2_render_phrase: requireExportedFunction(
      rawExports,
      "flt2_render_phrase",
    ) as ConcertGrandExports["flt2_render_phrase"],
    flt2_render: requireExportedFunction(
      rawExports,
      "flt2_render",
    ) as ConcertGrandExports["flt2_render"],
    clr_note_frames: requireExportedFunction(
      rawExports,
      "clr_note_frames",
    ) as ConcertGrandExports["clr_note_frames"],
    clr_render: requireExportedFunction(
      rawExports,
      "clr_render",
    ) as ConcertGrandExports["clr_render"],
    clr_render_seeded: requireExportedFunction(
      rawExports,
      "clr_render_seeded",
    ) as ConcertGrandExports["clr_render_seeded"],
    clr_render_expressive: requireExportedFunction(
      rawExports,
      "clr_render_expressive",
    ) as ConcertGrandExports["clr_render_expressive"],
    clr_render_v2: requireExportedFunction(
      rawExports,
      "clr_render_v2",
    ) as ConcertGrandExports["clr_render_v2"],
    clr_state_max_bytes_v2: requireExportedFunction(
      rawExports,
      "clr_state_max_bytes_v2",
    ) as ConcertGrandExports["clr_state_max_bytes_v2"],
    clr_state_fixed_bytes_v2: requireExportedFunction(
      rawExports,
      "clr_state_fixed_bytes_v2",
    ) as ConcertGrandExports["clr_state_fixed_bytes_v2"],
    clr_render_phrase_v2: requireExportedFunction(
      rawExports,
      "clr_render_phrase_v2",
    ) as ConcertGrandExports["clr_render_phrase_v2"],
    phs_validate_v2: requireExportedFunction(
      instance.exports,
      "phs_validate_v2",
    ) as ConcertGrandExports["phs_validate_v2"],
    phs_modal_render_v2: requireExportedFunction(
      instance.exports,
      "phs_modal_render_v2",
    ) as ConcertGrandExports["phs_modal_render_v2"],
    phs_reed_solve_v2: requireExportedFunction(
      instance.exports,
      "phs_reed_solve_v2",
    ) as ConcertGrandExports["phs_reed_solve_v2"],
    phs_clarinet_reed_step_v2: requireExportedFunction(
      instance.exports,
      "phs_clarinet_reed_step_v2",
    ) as ConcertGrandExports["phs_clarinet_reed_step_v2"],
  };
  const memory = exports.memory;
  /* Scratch region starts past the module's own data and shadow stack. */
  const heapBase =
    typeof exports.__heap_base?.value === "number"
      ? exports.__heap_base.value
      : memory.buffer.byteLength;
  const scratchBase = Math.ceil((heapBase + 1_024) / 16) * 16;
  let cooperativeRuntimeTail: Promise<void> = Promise.resolve();
  const runCooperativeRuntimeExclusive = <T>(
    task: () => Promise<T>,
  ): Promise<T> => {
    const result = cooperativeRuntimeTail.then(task, task);
    cooperativeRuntimeTail = result.then(
      () => undefined,
      () => undefined,
    );
    return result;
  };

  const cgRuntimeInit = exports.cg_runtime_init;
  const cgRuntimeMaxSteps = exports.cg_runtime_max_steps;
  const cgRuntimeReset = exports.cg_runtime_reset;
  const cgRuntimeStep = exports.cg_runtime_step;
  const cgRuntimeWrittenFrames = exports.cg_runtime_written_frames;
  const renderSynthesizedNoteCooperatively =
    cgRuntimeInit !== undefined &&
      cgRuntimeMaxSteps !== undefined &&
      cgRuntimeReset !== undefined &&
      cgRuntimeStep !== undefined &&
      cgRuntimeWrittenFrames !== undefined
      ? createConcertGrandCooperativeRenderFunction({
          memory,
          scratchBase: scratchBase + COOPERATIVE_CHORD_SCRATCH_OFFSET_BYTES,
          abi: Object.freeze({
            noteFrames: exports.cg_note_frames,
            runtimeInit: cgRuntimeInit,
            runtimeMaxSteps: cgRuntimeMaxSteps,
            runtimeReset: cgRuntimeReset,
            runtimeStep: cgRuntimeStep,
            runtimeWrittenFrames: cgRuntimeWrittenFrames,
          }),
          runExclusive: runCooperativeRuntimeExclusive,
        })
      : undefined;

  const pno2NoteFrames = exports.pno2_note_frames;
  const pno2RuntimeInit = exports.pno2_runtime_init;
  const pno2RuntimeMaxSteps = exports.pno2_runtime_max_steps;
  const pno2RuntimeStep = exports.pno2_runtime_step;
  const pno2RuntimeReset = exports.pno2_runtime_reset;
  const renderPhysicalAttackCooperatively =
    pno2NoteFrames !== undefined &&
      pno2RuntimeInit !== undefined &&
      pno2RuntimeMaxSteps !== undefined &&
      pno2RuntimeStep !== undefined &&
      pno2RuntimeReset !== undefined
      ? createPhysicalPianoAttackRenderFunction({
          memory,
          scratchBase: scratchBase + COOPERATIVE_CHORD_SCRATCH_OFFSET_BYTES,
          abi: Object.freeze({
            noteFrames: pno2NoteFrames,
            runtimeInit: pno2RuntimeInit,
            runtimeMaxSteps: pno2RuntimeMaxSteps,
            runtimeStep: pno2RuntimeStep,
            runtimeReset: pno2RuntimeReset,
          }),
          runExclusive: runCooperativeRuntimeExclusive,
        })
      : undefined;

  const pno2ChordRuntimeInit = exports.pno2_chord_runtime_init;
  const pno2ChordRuntimeMaxSteps = exports.pno2_chord_runtime_max_steps;
  const pno2ChordRuntimeStep = exports.pno2_chord_runtime_step;
  const pno2ChordRuntimeReset = exports.pno2_chord_runtime_reset;
  const renderPhysicalChordAttackCooperatively =
    pno2NoteFrames !== undefined &&
      pno2ChordRuntimeInit !== undefined &&
      pno2ChordRuntimeMaxSteps !== undefined &&
      pno2ChordRuntimeStep !== undefined &&
      pno2ChordRuntimeReset !== undefined
      ? createPhysicalPianoChordAttackRenderFunction({
          memory,
          scratchBase: scratchBase + COOPERATIVE_CHORD_SCRATCH_OFFSET_BYTES,
          abi: Object.freeze({
            noteFrames: pno2NoteFrames,
            runtimeInit: pno2ChordRuntimeInit,
            runtimeMaxSteps: pno2ChordRuntimeMaxSteps,
            runtimeStep: pno2ChordRuntimeStep,
            runtimeReset: pno2ChordRuntimeReset,
          }),
          runExclusive: runCooperativeRuntimeExclusive,
        })
      : undefined;

  const renderSynthesizedNote = (
    midiPitch: number,
    velocity: number,
    sampleRateHz: number,
    maxSeconds?: number,
  ): RenderedNotePcm | null => {
    const natural = exports.cg_note_frames(midiPitch, sampleRateHz);
    if (natural <= 0) return null;
    const capacity =
      maxSeconds === undefined || !Number.isFinite(maxSeconds)
        ? natural
        : Math.min(natural, Math.max(1, Math.round(maxSeconds * sampleRateHz)));
    const channelBytes = capacity * 4;
    const leftPointer = scratchBase;
    const rightPointer = scratchBase + channelBytes;
    ensureCapacity(memory, scratchBase, channelBytes * 2);
    const written = exports.cg_render(
      midiPitch,
      velocity,
      sampleRateHz,
      leftPointer,
      rightPointer,
      capacity,
    );
    if (written <= 0) return null;
    /* Copy out: the scratch region is reused by the next render. */
    const left = new Float32Array(written);
    const right = new Float32Array(written);
    left.set(new Float32Array(memory.buffer, leftPointer, written));
    right.set(new Float32Array(memory.buffer, rightPointer, written));
    return Object.freeze({
      sampleRateHz,
      frameCount: written,
      left,
      right,
    });
  };

  const renderNote = (
    midiPitch: number,
    velocity: number,
    sampleRateHz: number,
    maxSeconds?: number,
  ): RenderedNotePcm | null => {
    const synthesized = renderSynthesizedNote(
      midiPitch,
      velocity,
      sampleRateHz,
      maxSeconds,
    );
    if (synthesized === null) return null;
    applyAttackLayer(
      synthesized.left,
      synthesized.right,
      synthesized.frameCount,
      midiPitch,
      velocity,
      sampleRateHz,
    );
    if (maxSeconds === undefined || !Number.isFinite(maxSeconds)) {
      return synthesized;
    }
    const wanted = Math.max(1, Math.round(maxSeconds * sampleRateHz));
    if (wanted >= synthesized.frameCount) return synthesized;
    /* Fade the truncation over ~15 ms so the cut cannot click. */
    const fade = Math.min(Math.round(0.015 * sampleRateHz), wanted);
    const left = synthesized.left.slice(0, wanted);
    const right = synthesized.right.slice(0, wanted);
    for (let index = 0; index < fade; index += 1) {
      const gain = (fade - index) / fade;
      const at = wanted - fade + index;
      left[at] = (left[at] ?? 0) * gain;
      right[at] = (right[at] ?? 0) * gain;
    }
    return Object.freeze({
      sampleRateHz: synthesized.sampleRateHz,
      frameCount: wanted,
      left,
      right,
    });
  };

  const renderPhysicalNoteCooperatively =
    renderPhysicalAttackCooperatively === undefined ||
      renderSynthesizedNoteCooperatively === undefined
      ? undefined
      : async (
          midiPitch: number,
          velocity: number,
          sampleRateHz: number,
          maxSeconds?: number,
        ): Promise<RenderedNotePcm | null> => {
          const physical = await renderPhysicalAttackCooperatively(
            midiPitch,
            velocity,
            sampleRateHz,
            maxSeconds,
          );
          if (physical === null) return null;
          const synthesized = await renderSynthesizedNoteCooperatively(
            midiPitch,
            velocity,
            sampleRateHz,
            maxSeconds,
          );
          if (
            synthesized === null ||
            !applyPhysicalPianoAttackLayer(
              synthesized.left,
              synthesized.right,
              synthesized.frameCount,
              physical,
              sampleRateHz,
            )
          ) return null;
          return synthesized;
        };

  const MAX_DETECTED_NOTES = 12;

  const validatePhysicalAbiV2 = (
    request: PhysicalRenderAbiRequestV2,
    linearMemoryBytes: number,
  ): PhysicalRenderRefusalCode | null => {
    const outcome = exports.phs_validate_v2(
      request.abiVersion,
      request.requestByteLength,
      request.descriptorOffset,
      request.descriptorCount,
      request.controlPointOffset,
      request.controlPointCount,
      request.outputLeftOffset,
      request.outputRightOffset,
      request.outputCapacityFrames,
      request.stateInputOffset,
      request.stateInputByteLength,
      request.stateOutputOffset,
      request.stateOutputCapacityBytes,
      linearMemoryBytes,
    );
    if (outcome === 0) return null;
    if (outcome === 1) return "physical.schema_unsupported";
    if (outcome === 3) return "limit.physical_frames_exceeded";
    if (outcome === 4) return "limit.physical_control_points_exceeded";
    if (outcome === 5) return "physical.state_handoff_invalid";
    return "physical.abi_bounds_invalid";
  };

  const renderPhysicalModalV2: ConcertGrandRenderer["renderPhysicalModalV2"] =
    (request) => {
      if (
        !Number.isSafeInteger(request.frameCount) ||
        request.frameCount <= 0 ||
        request.frameCount > 2_880_000
      ) {
        return null;
      }
      const channelBytes = request.frameCount * 4;
      const leftPointer = scratchBase;
      const rightPointer = leftPointer + channelBytes;
      // The f64 state view requires 8-byte alignment; an odd frame count
      // leaves rightPointer + channelBytes at 4 mod 8, which the wasm-side
      // validator now refuses and a Float64Array view would throw on.
      const statePointer = Math.ceil((rightPointer + channelBytes) / 8) * 8;
      const energyPointer = Math.ceil((statePointer + 16) / 8) * 8;
      ensureCapacity(memory, scratchBase, energyPointer + 48 - scratchBase);
      const written = exports.phs_modal_render_v2(
        request.sampleRateHz,
        request.frequencyHz,
        request.dampingPerSecond,
        request.excitation,
        request.initialState.x,
        request.initialState.y,
        leftPointer,
        rightPointer,
        request.frameCount,
        statePointer,
        energyPointer,
      );
      if (written !== request.frameCount) return null;
      const left = new Float32Array(written);
      const right = new Float32Array(written);
      left.set(new Float32Array(memory.buffer, leftPointer, written));
      right.set(new Float32Array(memory.buffer, rightPointer, written));
      const state = new Float64Array(memory.buffer, statePointer, 2);
      const energy = new Float64Array(memory.buffer, energyPointer, 6);
      return Object.freeze({
        sampleRateHz: request.sampleRateHz,
        frameCount: written,
        left,
        right,
        state: Object.freeze({ x: state[0] ?? 0, y: state[1] ?? 0 }),
        energy: Object.freeze({
          initialEnergy: energy[0] ?? 0,
          excitationWork: energy[1] ?? 0,
          finalEnergy: energy[2] ?? 0,
          dampingLoss: energy[3] ?? 0,
          residual: energy[4] ?? 0,
        }),
        limiterEngagements: energy[5] ?? 0,
      });
    };

  const solvePhysicalReedV2: ConcertGrandRenderer["solvePhysicalReedV2"] =
    (request) => {
      const outputPointer = Math.ceil(scratchBase / 8) * 8;
      ensureCapacity(memory, scratchBase, outputPointer + 32 - scratchBase);
      const outcome = exports.phs_reed_solve_v2(
        request.mouthPressure,
        request.borePressure,
        request.opening,
        request.stiffness,
        request.boreImpedance,
        outputPointer,
      );
      if (outcome !== 1) return null;
      const values = new Float64Array(memory.buffer, outputPointer, 4);
      return Object.freeze({
        junctionPressure: values[0] ?? 0,
        volumeFlow: values[1] ?? 0,
        nonlinearIterations: values[2] ?? 0,
        fallbackBisections: values[3] ?? 0,
      });
    };

  const stepPhysicalClarinetReedV2: ConcertGrandRenderer["stepPhysicalClarinetReedV2"] =
    (request) => {
      const outputPointer = Math.ceil(scratchBase / 8) * 8;
      ensureCapacity(memory, scratchBase, outputPointer + 64 - scratchBase);
      const outcome = exports.phs_clarinet_reed_step_v2(
        request.dtSeconds, request.state.displacementM, request.state.velocityMPerS,
        request.mouthPressurePa, request.mouthpiecePressurePa, request.massKg,
        request.dampingNsPerM, request.stiffnessNPerM, request.equilibriumOpeningM,
        request.effectiveAreaM2, request.channelWidthM, request.airDensityKgPerM3,
        request.tongueContact, outputPointer,
      );
      if (outcome !== 1) return null;
      const value = new Float64Array(memory.buffer, outputPointer, 8);
      return Object.freeze({
        state: Object.freeze({ displacementM: value[0] ?? 0, velocityMPerS: value[1] ?? 0 }),
        signedVolumeFlowM3PerS: value[2] ?? 0,
        collisionLossJ: value[3] ?? 0,
        mechanicalEnergyBeforeJ: value[4] ?? 0,
        mechanicalEnergyAfterJ: value[5] ?? 0,
        tongueForceN: value[6] ?? 0,
        contact: value[7] === 1,
      });
    };

  const analyzeWindow = (
    samples: Float32Array,
    sampleRateHz: number,
  ): AnalysisFrame | null => {
    const fftSize = samples.length;
    if (
      fftSize < 64 ||
      fftSize > 8_192 ||
      (fftSize & (fftSize - 1)) !== 0 ||
      !Number.isFinite(sampleRateHz) ||
      sampleRateHz <= 0
    ) {
      return null;
    }
    const binCount = fftSize / 2;
    /*
     * Scratch layout: input window, magnitude bins, note triples, chroma —
     * all in the same reusable region past the render scratch.
     */
    const inputPointer = scratchBase;
    const magnitudesPointer = inputPointer + fftSize * 4;
    const notesPointer = magnitudesPointer + binCount * 4;
    const chromaPointer = notesPointer + MAX_DETECTED_NOTES * 3 * 4;
    ensureCapacity(memory, scratchBase, chromaPointer + 12 * 4 - scratchBase);
    new Float32Array(memory.buffer, inputPointer, fftSize).set(samples);
    const bins = exports.an_spectrum(inputPointer, fftSize, magnitudesPointer);
    if (bins !== binCount) return null;
    const noteCount = exports.an_notes(
      magnitudesPointer,
      bins,
      sampleRateHz,
      fftSize,
      notesPointer,
      MAX_DETECTED_NOTES,
    );
    const chromaCount = exports.an_chroma(
      magnitudesPointer,
      bins,
      sampleRateHz,
      fftSize,
      chromaPointer,
    );
    if (chromaCount !== 12 || noteCount < 0) return null;
    const magnitudes = new Float32Array(binCount);
    magnitudes.set(new Float32Array(memory.buffer, magnitudesPointer, binCount));
    const chroma = new Float32Array(12);
    chroma.set(new Float32Array(memory.buffer, chromaPointer, 12));
    const triples = new Float32Array(memory.buffer, notesPointer, noteCount * 3);
    const notes: DetectedNote[] = [];
    for (let index = 0; index < noteCount; index += 1) {
      notes.push(
        Object.freeze({
          midiPitch: triples[index * 3] ?? 0,
          centsDeviation: triples[index * 3 + 1] ?? 0,
          strength: triples[index * 3 + 2] ?? 0,
        }),
      );
    }
    return Object.freeze({
      sampleRateHz,
      fftSize,
      magnitudes,
      notes: Object.freeze(notes),
      chroma,
    });
  };

  /*
   * Waveguide renderers (physically modeled guitar and flute) live in the
   * same wasm instance and share the scratch region. Each is the same
   * render-copy-truncate shape as the piano's synthesized path; the models
   * bake their own musical envelopes, so the only post-processing is the
   * click-guard fade on an explicit truncation.
   */
  const makeWaveguideRenderNote = (
    noteFrames: (midi: number, rate: number) => number,
    renderInto: (
      midi: number,
      velocity: number,
      rate: number,
      left: number,
      right: number,
      maxFrames: number,
    ) => number,
    renderSeededInto?: (
      midi: number,
      velocity: number,
      rate: number,
      variationSlot: number,
      left: number,
      right: number,
      maxFrames: number,
    ) => number,
    renderExpressiveInto?: (
      midi: number,
      velocity: number,
      rate: number,
      variationSlot: number,
      articulation: number,
      left: number,
      right: number,
      maxFrames: number,
    ) => number,
  ): WaveguideRenderer["renderNote"] => {
    return (
      midiPitch,
      velocity,
      sampleRateHz,
      maxSeconds,
      variationSlot,
      windArticulation,
    ) => {
      const runtimeWindArticulation: unknown = windArticulation;
      if (
        runtimeWindArticulation !== undefined &&
        runtimeWindArticulation !== "legato" &&
        runtimeWindArticulation !== "tongued"
      ) return null;
      const natural = noteFrames(midiPitch, sampleRateHz);
      if (natural <= 0) return null;
      const capacity =
        maxSeconds === undefined || !Number.isFinite(maxSeconds)
          ? natural
          : Math.min(
              natural,
              Math.max(1, Math.round(maxSeconds * sampleRateHz)),
            );
      const channelBytes = capacity * 4;
      const leftPointer = scratchBase;
      const rightPointer = scratchBase + channelBytes;
      ensureCapacity(memory, scratchBase, channelBytes * 2);
      const articulationCode = windArticulation === "legato" ? 0 : 1;
      const written = variationSlot !== undefined &&
          windArticulation !== undefined &&
          renderExpressiveInto !== undefined
        ? renderExpressiveInto(
            midiPitch,
            velocity,
            sampleRateHz,
            variationSlot,
            articulationCode,
            leftPointer,
            rightPointer,
            capacity,
          )
        : variationSlot !== undefined && renderSeededInto !== undefined
        ? renderSeededInto(
            midiPitch,
            velocity,
            sampleRateHz,
            variationSlot,
            leftPointer,
            rightPointer,
            capacity,
          )
        : renderInto(
            midiPitch,
            velocity,
            sampleRateHz,
            leftPointer,
            rightPointer,
            capacity,
          );
      if (written <= 0) return null;
      const left = new Float32Array(written);
      const right = new Float32Array(written);
      left.set(new Float32Array(memory.buffer, leftPointer, written));
      right.set(new Float32Array(memory.buffer, rightPointer, written));
      /*
       * Finite-output guard (2026-08-09 review): the Rust finalize path
       * only rejects rms <= 0.0, and NaN fails every comparison — a
       * waveguide instability can hand back a "successful" buffer full of
       * NaN (the measured 2026-08-08 flute failure mode). The piano and
       * plucked paths already guard; winds must refuse loudly too, never
       * ship silence into an AudioBuffer.
       */
      for (let index = 0; index < written; index += 1) {
        if (
          !Number.isFinite(left[index] ?? 0) ||
          !Number.isFinite(right[index] ?? 0)
        ) {
          return null;
        }
      }
      if (written === capacity && capacity < natural) {
        /* Truncated by the caller: fade ~15 ms so the cut cannot click. */
        const fade = Math.min(Math.round(0.015 * sampleRateHz), written);
        for (let index = 0; index < fade; index += 1) {
          const gain = (fade - index) / fade;
          const at = written - fade + index;
          left[at] = (left[at] ?? 0) * gain;
          right[at] = (right[at] ?? 0) * gain;
        }
      }
      return Object.freeze({
        sampleRateHz,
        frameCount: written,
        left,
        right,
      });
    };
  };

  const renderFluteV2PhraseFresh = (
    midi: number,
    requestedVelocity: number,
    rate: number,
    variationSlot: number,
    articulation: number,
    leftPointer: number,
    rightPointer: number,
    maxFrames: number,
  ): number => {
    /*
     * Drive stays inside the reference-certified dynamics envelope. The
     * register-2 fingerings collapse to the fundamental an octave down when
     * blown past it (measured 2026-08-08: m72 clean at velocity 36/72,
     * -1197 cents at 108; the upper-register ff cells were never admitted
     * by the UIowa matrix -- the documented two-mode wall). Loudness still
     * follows the true velocity through the voice gain curve; forte renders
     * the certified mf-side timbre instead of the wrong octave. Lift the
     * cap only when the two-mode coexistence work certifies ff cells.
     */
    const velocity = Math.min(requestedVelocity, midi >= 72 ? 72 : 90);
    const stateCapacity = exports.flt2_state_max_bytes();
    const statePointer = (rightPointer + maxFrames * 4 + 7) & ~7;
    ensureCapacity(
      memory,
      statePointer,
      Math.max(0, stateCapacity),
    );
    return exports.flt2_render_phrase(
      midi,
      velocity,
      rate,
      variationSlot,
      articulation,
      leftPointer,
      rightPointer,
      maxFrames,
      0,
      0,
      statePointer,
      stateCapacity,
    );
  };

  const makePluckedChordRenders = (
    packIndex: number,
  ): PluckedChordRenderFunctions => createPluckedChordRenderFunctions({
    packIndex,
    memory,
    scratchBase,
    /*
     * The cooperative session remains live across macrotask yields. Keep it
     * above every synchronous scratch allocation, then serialize every PLK2
     * pack and the dark PNO2 attack because they deliberately share this
     * bounded region.
     */
    cooperativeScratchBase: scratchBase + COOPERATIVE_CHORD_SCRATCH_OFFSET_BYTES,
    abi: Object.freeze({
      noteFrames: exports.plk2_note_frames,
      physicalSampleRate: exports.plk2_chord_physical_sample_rate ?? (() => 0),
      ...(exports.plk2_render_chord === undefined
        ? {}
        : { renderChordInto: exports.plk2_render_chord }),
      ...(exports.plk2_chord_session_state_max_bytes === undefined
        ? {}
        : { sessionStateMaxBytes: exports.plk2_chord_session_state_max_bytes }),
      ...(exports.plk2_chord_session_max_steps === undefined
        ? {}
        : { sessionMaxSteps: exports.plk2_chord_session_max_steps }),
      ...(exports.plk2_chord_session_init === undefined
        ? {}
        : { sessionInit: exports.plk2_chord_session_init }),
      ...(exports.plk2_chord_session_step === undefined
        ? {}
        : { sessionStep: exports.plk2_chord_session_step }),
      ...(exports.plk2_chord_runtime_init === undefined
        ? {}
        : { runtimeInit: exports.plk2_chord_runtime_init }),
      ...(exports.plk2_chord_runtime_max_steps === undefined
        ? {}
        : { runtimeMaxSteps: exports.plk2_chord_runtime_max_steps }),
      ...(exports.plk2_chord_runtime_step === undefined
        ? {}
        : { runtimeStep: exports.plk2_chord_runtime_step }),
      ...(exports.plk2_chord_runtime_reset === undefined
        ? {}
        : { runtimeReset: exports.plk2_chord_runtime_reset }),
    }),
    runExclusive: runCooperativeRuntimeExclusive,
  });

  const renderClarinetPhraseSegment: NonNullable<
    WaveguideRenderer["renderPhraseSegment"]
  > = (
    midiPitch,
    velocity,
    sampleRateHz,
    frameCount,
    stateInput,
    variationSlot,
    windArticulation,
  ) => {
    const runtimeWindArticulation: unknown = windArticulation;
    if (
      !Number.isSafeInteger(frameCount) || frameCount <= 0 ||
      !Number.isSafeInteger(variationSlot) || variationSlot < 0 ||
      (runtimeWindArticulation !== "legato" &&
        runtimeWindArticulation !== "tongued")
    ) return null;
    const natural = exports.clr_note_frames(midiPitch, sampleRateHz);
    const stateCapacity = exports.clr_state_max_bytes_v2();
    const stateFixedBytes = exports.clr_state_fixed_bytes_v2();
    if (
      natural <= 0 || frameCount > natural || stateCapacity <= 0 ||
      stateFixedBytes <= 0 || stateFixedBytes > stateCapacity ||
      (stateInput !== null && stateInput.byteLength > stateCapacity)
    ) return null;
    const channelBytes = frameCount * 4;
    const leftPointer = scratchBase;
    const rightPointer = leftPointer + channelBytes;
    const stateInputPointer = Math.ceil((rightPointer + channelBytes) / 8) * 8;
    const stateInputBytes = stateInput?.byteLength ?? 0;
    const stateOutputPointer = Math.ceil(
      (stateInputPointer + stateInputBytes) / 8,
    ) * 8;
    ensureCapacity(
      memory,
      scratchBase,
      stateOutputPointer + stateCapacity - scratchBase,
    );
    if (stateInput !== null) {
      new Uint8Array(memory.buffer, stateInputPointer, stateInputBytes).set(stateInput);
    }
    const written = exports.clr_render_phrase_v2(
      midiPitch,
      velocity,
      sampleRateHz,
      variationSlot,
      windArticulation === "legato" ? 0 : 1,
      leftPointer,
      rightPointer,
      frameCount,
      stateInputBytes === 0 ? 0 : stateInputPointer,
      stateInputBytes,
      stateOutputPointer,
      stateCapacity,
    );
    if (written <= 0 || written > frameCount) return null;
    const stateView = new DataView(memory.buffer, stateOutputPointer, stateCapacity);
    const boreLength = stateView.getUint32(16, true);
    const stateBytes = stateFixedBytes + boreLength * 8;
    if (boreLength < 3 || stateBytes > stateCapacity) return null;
    const left = new Float32Array(written);
    const right = new Float32Array(written);
    left.set(new Float32Array(memory.buffer, leftPointer, written));
    right.set(new Float32Array(memory.buffer, rightPointer, written));
    const stateOutput = new Uint8Array(stateBytes);
    stateOutput.set(new Uint8Array(memory.buffer, stateOutputPointer, stateBytes));
    return Object.freeze({
      sampleRateHz,
      frameCount: written,
      left,
      right,
      stateOutput,
    });
  };

  const makePluckedStemSegment = (
    packIndex: number,
  ): NonNullable<WaveguideRenderer["renderPluckedStemSegment"]> | undefined => {
    const stateMaxBytesFor = exports.plk2_stem_state_max_bytes;
    const renderMaxFramesFor = exports.plk2_stem_render_max_frames;
    const initialize = exports.plk2_stem_init;
    const render = exports.plk2_stem_render;
    if (
      stateMaxBytesFor === undefined || renderMaxFramesFor === undefined ||
      initialize === undefined || render === undefined
    ) return undefined;
    return (
      midiPitch,
      velocity,
      sampleRateHz,
      frameCount,
      stateInput,
      reset,
    ) => {
      if (
        !Number.isSafeInteger(packIndex) || packIndex < 0 ||
        !Number.isSafeInteger(frameCount) || frameCount <= 0 ||
        !Number.isFinite(sampleRateHz) ||
        (midiPitch === null
          ? velocity !== 0
          : !Number.isSafeInteger(midiPitch) ||
            !Number.isSafeInteger(velocity) || velocity < 1 || velocity > 127)
      ) return null;
      const stateCapacity = stateMaxBytesFor();
      const maximumFrames = renderMaxFramesFor();
      if (
        !Number.isSafeInteger(stateCapacity) || stateCapacity <= 0 ||
        stateCapacity > 64 * 1_024 ||
        !Number.isSafeInteger(maximumFrames) || maximumFrames <= 0 ||
        frameCount > maximumFrames ||
        (stateInput !== null &&
          (stateInput.byteLength <= 0 || stateInput.byteLength > stateCapacity))
      ) return null;
      const statePointer = scratchBase;
      const leftPointer = Math.ceil((statePointer + stateCapacity) / 4) * 4;
      const channelBytes = frameCount * 4;
      const rightPointer = leftPointer + channelBytes;
      ensureCapacity(
        memory,
        scratchBase,
        rightPointer + channelBytes - scratchBase,
      );
      let stateBytes: number;
      if (stateInput === null) {
        stateBytes = initialize(
          packIndex,
          sampleRateHz,
          statePointer,
          stateCapacity,
        );
      } else {
        stateBytes = stateInput.byteLength;
        new Uint8Array(memory.buffer, statePointer, stateBytes).set(stateInput);
      }
      if (stateBytes <= 0 || stateBytes > stateCapacity) return null;
      const eventFlags = (midiPitch === null ? 0 : 1) | (reset ? 2 : 0);
      const written = render(
        statePointer,
        stateBytes,
        midiPitch ?? -1,
        midiPitch === null ? 0 : velocity,
        eventFlags,
        leftPointer,
        rightPointer,
        frameCount,
      );
      if (written !== frameCount) return null;
      const left = new Float32Array(written);
      const right = new Float32Array(written);
      left.set(new Float32Array(memory.buffer, leftPointer, written));
      right.set(new Float32Array(memory.buffer, rightPointer, written));
      const stateOutput = new Uint8Array(stateBytes);
      stateOutput.set(new Uint8Array(memory.buffer, statePointer, stateBytes));
      return Object.freeze({
        sampleRateHz,
        frameCount: written,
        left,
        right,
        stateOutput,
      });
    };
  };

  const renderUprightBassStemSegment = makePluckedStemSegment(
    PLK2_UPRIGHT_BASS_PACK_INDEX,
  );

  const waveguide = new Map<string, WaveguideRenderer>();
  for (const [algorithmId, renderNoteFor] of [
    [
      PLUCKED_ARCHTOP_V2_ALGORITHM_ID,
      makeWaveguideRenderNote(
        (m, r) => exports.plk2_note_frames(0, m, r),
        (m, v, r, l, rt, mx) => exports.plk2_render(0, m, v, r, l, rt, mx),
      ),
    ],
    [
      PLUCKED_ELECTRIC_V2_ALGORITHM_ID,
      makeWaveguideRenderNote(
        (m, r) => exports.plk2_note_frames(1, m, r),
        (m, v, r, l, rt, mx) => exports.plk2_render(1, m, v, r, l, rt, mx),
      ),
    ],
    [
      PLUCKED_DREADNOUGHT_ALGORITHM_ID,
      makeWaveguideRenderNote(
        (m, r) => exports.plk2_note_frames(2, m, r),
        (m, v, r, l, rt, mx) => exports.plk2_render(2, m, v, r, l, rt, mx),
      ),
    ],
    [
      PLUCKED_UKULELE_ALGORITHM_ID,
      makeWaveguideRenderNote(
        (m, r) => exports.plk2_note_frames(3, m, r),
        (m, v, r, l, rt, mx) => exports.plk2_render(3, m, v, r, l, rt, mx),
      ),
    ],
    [
      PLUCKED_UPRIGHT_BASS_ALGORITHM_ID,
      makeWaveguideRenderNote(
        (m, r) => exports.plk2_note_frames(4, m, r),
        (m, v, r, l, rt, mx) => exports.plk2_render(4, m, v, r, l, rt, mx),
      ),
    ],
    [
      VIBES_V2_ALGORITHM_ID,
      makeWaveguideRenderNote(
        exports.vbs2_note_frames,
        (m, v, r, l, rt, mx) => exports.vbs2_render(m, v, r, l, rt, mx),
      ),
    ],
    [
      WAVEGUIDE_GUITAR_CLEAN_ALGORITHM_ID,
      makeWaveguideRenderNote(exports.gtr_note_frames, (m, v, r, l, rt, mx) =>
        exports.gtr_render(m, v, r, 0, l, rt, mx),
      ),
    ],
    [
      WAVEGUIDE_GUITAR_DRIVE_ALGORITHM_ID,
      makeWaveguideRenderNote(exports.gtr_note_frames, (m, v, r, l, rt, mx) =>
        exports.gtr_render(m, v, r, 1, l, rt, mx),
      ),
    ],
    [
      WAVEGUIDE_FLUTE_ALGORITHM_ID,
      /*
       * Gesture renders deliberately fall back to the plain export. The
       * seeded/expressive flute paths are numerically broken in the shipped
       * wasm: measured 2026-08-08, slots 1-7 detune -171..+1062 cents
       * (wrong-regime locks) and every slot render goes NaN after ~1 s,
       * which browsers play as silence. The owner heard both ("out of
       * tune", "quiet"). The plain path measures +-2 cents at every chart
       * velocity and articulation. Re-enable seeded dispatch only after the
       * Rust exports pass a per-slot tuning + finite-output gate.
       */
      makeWaveguideRenderNote(
        exports.flt_note_frames,
        (m, v, r, l, rt, mx) => exports.flt_render(m, v, r, l, rt, mx),
      ),
    ],
    [
      WAVEGUIDE_FLUTE_V2_ALGORITHM_ID,
      /*
       * Every flute@2 render goes through flt2_render_phrase with a fresh
       * (zero-length) incoming state -- the exact call the UIowa reference
       * matrix certifies. The standalone flt2_render entry was measured
       * 2026-08-08 rendering the second register octave-wrong through the
       * production wrapper (m72/75/77/78/79/87/88 at -1200 cents, m81 +622,
       * m83 -1902) while the phrase path is calibrated; shipping the
       * uncertified sibling path is the same oracle-fidelity trap this
       * campaign has hit before. Slot/articulation pass through when the
       * engine provides them (gesture path); the plain path keeps the
       * reviewed slot-0/tongued defaults.
       */
      makeWaveguideRenderNote(
        exports.flt2_note_frames,
        (m, v, r, l, rt, mx) =>
          renderFluteV2PhraseFresh(m, v, r, 0, 1, l, rt, mx),
        (m, v, r, slot, l, rt, mx) =>
          renderFluteV2PhraseFresh(m, v, r, slot, 1, l, rt, mx),
        (m, v, r, slot, articulation, l, rt, mx) =>
          renderFluteV2PhraseFresh(m, v, r, slot, articulation, l, rt, mx),
      ),
    ],
    [
      WAVEGUIDE_CLARINET_ALGORITHM_ID,
      makeWaveguideRenderNote(
        exports.clr_note_frames,
        (m, v, r, l, rt, mx) => exports.clr_render(m, v, r, l, rt, mx),
        (m, v, r, slot, l, rt, mx) =>
          exports.clr_render_seeded(m, v, r, slot, l, rt, mx),
        (m, v, r, slot, articulation, l, rt, mx) =>
          exports.clr_render_expressive(
            m,
            v,
            r,
            slot,
            articulation,
            l,
            rt,
            mx,
          ),
      ),
    ],
    [
      WAVEGUIDE_CLARINET_V2_ALGORITHM_ID,
      makeWaveguideRenderNote(
        exports.clr_note_frames,
        (m, v, r, l, rt, mx) => exports.clr_render_v2(m, v, r, 0, 1, l, rt, mx),
        (m, v, r, slot, l, rt, mx) => exports.clr_render_v2(m, v, r, slot, 1, l, rt, mx),
        (m, v, r, slot, articulation, l, rt, mx) =>
          exports.clr_render_v2(m, v, r, slot, articulation, l, rt, mx),
      ),
    ],
  ] as const) {
    waveguide.set(
      algorithmId,
      Object.freeze({
        algorithmId,
        wasmSha256: CONCERT_GRAND_WASM_SHA256,
        renderNote: renderNoteFor,
      }),
    );
  }
  for (const [algorithmId, packIndex] of [
    [PLUCKED_ARCHTOP_V2_ALGORITHM_ID, 0],
    [PLUCKED_ELECTRIC_V2_ALGORITHM_ID, 1],
    [PLUCKED_DREADNOUGHT_ALGORITHM_ID, 2],
    [PLUCKED_UKULELE_ALGORITHM_ID, 3],
    [PLUCKED_UPRIGHT_BASS_ALGORITHM_ID, PLK2_UPRIGHT_BASS_PACK_INDEX],
  ] as const) {
    const subject = waveguide.get(algorithmId);
    if (subject === undefined) throw new Error(`DSP_PLUCKED_RENDERER_MISSING:${algorithmId}`);
    const chordRenders = makePluckedChordRenders(packIndex);
    if (Object.keys(chordRenders).length !== 0) {
      waveguide.set(
        algorithmId,
        Object.freeze({ ...subject, ...chordRenders }),
      );
    }
  }
  const uprightBass = waveguide.get(PLUCKED_UPRIGHT_BASS_ALGORITHM_ID);
  if (uprightBass === undefined) throw new Error("DSP_UPRIGHT_BASS_MISSING");
  if (renderUprightBassStemSegment !== undefined) {
    waveguide.set(
      PLUCKED_UPRIGHT_BASS_ALGORITHM_ID,
      Object.freeze({
        ...uprightBass,
        renderPluckedStemSegment: renderUprightBassStemSegment,
      }),
    );
  }
  const clarinetV2 = waveguide.get(WAVEGUIDE_CLARINET_V2_ALGORITHM_ID);
  if (clarinetV2 === undefined) throw new Error("DSP_CLARINET_V2_MISSING");
  waveguide.set(
    WAVEGUIDE_CLARINET_V2_ALGORITHM_ID,
    Object.freeze({ ...clarinetV2, renderPhraseSegment: renderClarinetPhraseSegment }),
  );

  return Object.freeze({
    concertGrand: Object.freeze({
      algorithmId: CONCERT_GRAND_RENDERER_ALGORITHM_ID,
      wasmSha256: CONCERT_GRAND_WASM_SHA256,
      attackSamplesSha256: PIANO_ATTACK_SAMPLES_SHA256,
      ...(renderPhysicalAttackCooperatively === undefined
        ? {}
        : {
            physicalAttackAlgorithmId:
              CONCERT_GRAND_PHYSICAL_V2_ALGORITHM_ID,
            renderPhysicalAttackCooperatively,
            ...(renderPhysicalNoteCooperatively === undefined
              ? {}
              : { renderPhysicalNoteCooperatively }),
            ...(renderPhysicalChordAttackCooperatively === undefined
              ? {}
              : { renderPhysicalChordAttackCooperatively }),
          }),
      renderNote,
      renderSynthesizedNote,
      ...(renderSynthesizedNoteCooperatively === undefined
        ? {}
        : { renderSynthesizedNoteCooperatively }),
      attackSliceFor: selectAttackSlice,
      analyzeWindow,
      validatePhysicalAbiV2,
      renderPhysicalModalV2,
      solvePhysicalReedV2,
      stepPhysicalClarinetReedV2,
    }),
    waveguide,
  });
}

/**
 * Instantiate the module once per page. A rejected instantiation is not
 * cached: a later caller may retry, and the engine surfaces the stable
 * refusal `audio.renderer_unavailable` in the meantime.
 */
export function loadConcertGrandRenderer(): Promise<ConcertGrandRenderer> {
  return loadDspCore().then((core) => core.concertGrand);
}

/**
 * The waveguide renderer map, keyed by algorithm id — same instantiation,
 * same retry semantics.
 */
export function loadWaveguideRenderers(): Promise<
  ReadonlyMap<string, WaveguideRenderer>
> {
  return loadDspCore().then((core) => core.waveguide);
}

function loadDspCore(): Promise<DspCore> {
  rendererPromise ??= instantiate().catch((error: unknown) => {
    rendererPromise = null;
    throw error instanceof Error ? error : new Error(String(error));
  });
  return rendererPromise;
}
